steps.run:
case "$PROMOTION_PHASE" in
  candidate)
    ref_pattern='^refs/heads/release/promote-[0-9]+$'
    [ "$RUN_REF" = "refs/heads/release/promote-${PROMOTION_RUN%-*}" ] || {
      echo "::error::Candidate branch does not belong to the qualifying promotion."
      exit 1
    }
    ;;
  release) ref_pattern='^refs/tags/promote-[0-9]{14}-[0-9a-f]{8}$' ;;
  *) echo "::error::Unknown promotion qualification phase."; exit 1 ;;
esac
[[ "$EXPECTED_SHA" =~ ^[0-9a-f]{40}$ ]] &&
[[ "$PROMOTION_RUN" =~ ^[0-9]+-[0-9]+$ ]] &&
[[ "$RUN_REF" =~ $ref_pattern ]] &&
[ "$RUN_SHA" = "$EXPECTED_SHA" ] && [ "$WORKFLOW_SHA" = "$EXPECTED_SHA" ] || {
  echo "::error::Promotion dispatch does not execute the exact qualification snapshot."
  exit 1
}
